import { useRef, useState } from "react";
import { StyleSheet, Text, TextInput, View } from "react-native";
import type { StyleProp, TextStyle, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface OtpInputProps {
  length?: number;
  value?: string;
  onChange?: (value: string) => void;
  label: string;
  description?: string;
  error?: string;
  autoFocus?: boolean;
  disabled?: boolean;
  inputMode?: "numeric" | "text";
  /** Style of the field wrapper. */
  style?: StyleProp<ViewStyle>;
  /** Extend the inner, named parts of the OTP input: label, cell, cellText or hint. The React Native counterpart of `classNames`. */
  styles?: {
    label?: StyleProp<TextStyle>;
    cell?: StyleProp<ViewStyle>;
    cellText?: StyleProp<TextStyle>;
    hint?: StyleProp<TextStyle>;
  };
}

/** One hidden input holds the code, so paste, autofill from SMS and the keyboard all work; the cells only draw it. */
export function OtpInput({ length = 6, value = "", onChange, label, description, error, autoFocus = false, disabled = false, inputMode = "numeric", style, styles: parts }: OtpInputProps) {
  const tokens = useTokens();
  const input = useRef<TextInput>(null);
  const [focused, setFocused] = useState(false);
  const digits = value.slice(0, length).split("");

  return (
    <View style={[local.field, style]}>
      <Text style={[local.label, { color: tokens.foreground }, parts?.label]}>{label}</Text>
      <View style={local.row} onTouchEnd={() => input.current?.focus()}>
        {Array.from({ length }, (_, index) => {
          const active = focused && index === Math.min(digits.length, length - 1);
          return (
            <View
              key={index}
              style={[
                local.cell,
                { borderColor: error ? tokens.danger : active ? tokens.foreground : tokens.borderStrong, backgroundColor: disabled ? tokens.surfaceMuted : tokens.surface },
                parts?.cell,
              ]}
            >
              <Text style={[{ color: tokens.foreground, fontSize: 20, fontWeight: "500", fontVariant: ["tabular-nums"] }, parts?.cellText]}>{digits[index] ?? ""}</Text>
            </View>
          );
        })}
        <TextInput
          ref={input}
          value={value}
          onChangeText={(text) => onChange?.((inputMode === "numeric" ? text.replace(/\D/g, "") : text).slice(0, length))}
          maxLength={length}
          autoFocus={autoFocus}
          editable={!disabled}
          keyboardType={inputMode === "numeric" ? "number-pad" : "default"}
          textContentType="oneTimeCode"
          autoComplete="sms-otp"
          accessibilityLabel={label}
          onFocus={() => setFocused(true)}
          onBlur={() => setFocused(false)}
          style={local.hidden}
        />
      </View>
      {error ? (
        <Text accessibilityRole="alert" style={[local.hint, { color: tokens.danger }, parts?.hint]}>{error}</Text>
      ) : description ? (
        <Text style={[local.hint, { color: tokens.textMuted }, parts?.hint]}>{description}</Text>
      ) : null}
    </View>
  );
}

const local = StyleSheet.create({
  field: { alignSelf: "flex-start", gap: metrics.space[2] },
  label: { fontSize: metrics.text.sm, fontWeight: "500" },
  row: { flexDirection: "row", gap: 8 },
  cell: { width: 44, height: 52, alignItems: "center", justifyContent: "center", borderWidth: 1, borderRadius: metrics.radiusControl },
  hidden: { position: "absolute", width: "100%", height: "100%", opacity: 0 },
  hint: { fontSize: metrics.text.xs },
});

export default OtpInput;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
